import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect, vi } from "vitest";
import { screen, render, fireEvent } from "@testing-library/react";
import { ErrorCode } from "../ErrorCode";
const props = {
    errorCode: "401",
    goBack: () => vi.fn(),
};
Object.defineProperty(window, "location", {
    value: { reload: vi.fn() },
    writable: true,
});
describe("Rapid7 ErrorCode", () => {
    it("Should render with a 401 error", () => {
        render(_jsx(ErrorCode, { ...props }));
        expect(screen.getByText("401 = Not authorized")).toBeInTheDocument();
    });
    it("Should render with a 403 error", () => {
        render(_jsx(ErrorCode, { ...props, errorCode: "403" }));
        expect(screen.getByText("403 = Forbidden")).toBeInTheDocument();
    });
    it("Should render with a 404 error", () => {
        render(_jsx(ErrorCode, { ...props, errorCode: "404" }));
        expect(screen.getByText("404 = Page not found")).toBeInTheDocument();
    });
    it("Should render with a 406 error", () => {
        render(_jsx(ErrorCode, { ...props, errorCode: "406" }));
        expect(screen.getByText("406 = Not acceptable")).toBeInTheDocument();
    });
    it("Should render with a 409 error", () => {
        render(_jsx(ErrorCode, { ...props, errorCode: "409" }));
        expect(screen.getByText("409 = Conflict")).toBeInTheDocument();
    });
    it("Should render with a 500 error", () => {
        render(_jsx(ErrorCode, { ...props, errorCode: "500" }));
        expect(screen.getByText("500 = Internal server")).toBeInTheDocument();
    });
    it("Should render a reload button and reload if the error code is 500", () => {
        render(_jsx(ErrorCode, { ...props, errorCode: "500" }));
        const button = screen.getByRole("button");
        expect(button).toHaveTextContent("Reload");
        fireEvent.click(button);
        expect(window.location.reload).toHaveBeenCalledTimes(1);
    });
});
